// === Tab: mySketch ===
// Title: Trace / No Trace — Layers of Time and Motion
// Theme: color × motion × layers

let bg, bg1, bg2, bg3;
let angle = 0;

function setup() {
	createCanvas(400, 400);

	// Create 4 layer buffers (each quadrant)
	bg = createGraphics(width / 2, height / 2);
	bg1 = createGraphics(width / 2, height / 2);
	bg2 = createGraphics(width / 2, height / 2);
	bg3 = createGraphics(width / 2, height / 2);

	// Use HSB color mode for some layers
	bg2.colorMode(HSB, 360, 100, 100, 1);
	bg3.colorMode(HSB, 360, 100, 100, 1);
}

function draw() {
	noStroke();
	colorMode(RGB);

	// --- Top-left (trace: background) ---
	Layer();

	// rotating circle (clockwise)
	push();
	translate(width / 2, height / 2);
	rotate(angle);
	fill(255, 250, 100, 175);
	circle(50, 0, 50);
	pop();

	// --- Bottom-left (no trace: clear) ---
	Layer1();

	// rotating circle (counter rotation)
	push();
	translate(width / 2, height / 2);
	rotate(-angle);
	fill(255, 0, 0, 175);
	circle(-100, 0, 50);
	pop();

	// --- Bottom-right (colored trace) ---
	Layer2();

	// --- Top-right (colored no trace) ---
	Layer3();

	// Switch to HSB for front circles
	colorMode(HSB, 360, 100, 100, 1);

	// rotating circle (HSB color)
	push();
	translate(width / 2, height / 2);
	rotate(angle);
	fill(255, 95, 95, 0.5);
	circle(150, 0, 50);
	pop();

	push();
	translate(width / 2, height / 2);
	rotate(-angle);
	fill(90, 95, 95, 0.5);
	circle(-200, 0, 50);
	pop();

	// animation speed
	angle += 0.01;
}

// --- Layer: with trace (accumulation) ---
function Layer() {
	// background creates fading trail
	bg.background(80, 30);

	for (let x = 0; x < width / 2; x += 2) {
		let nx = 0.05 * x;
		let nt = sin(frameCount * 0.01) * 0.55;

		// noise-based vertical motion
		let y = 150 * noise(nx, nt);

		bg.stroke(255, 30);
		bg.strokeWeight(2);
		bg.line(x, 0, x, y);
	}

	image(bg, 0, 0);
}

// --- Layer: no trace (instant) ---
function Layer1() {
	// clear removes previous frame
	bg1.clear();

	for (let x = 0; x < width / 2; x += 2) {
		var nx = 0.05 * x;
		var nt = sin(frameCount * 0.01) * 0.55;

		var y = 150 * noise(nx, nt);

		bg1.stroke(255, 30);
		bg1.strokeWeight(2);

		// add sine oscillation
		bg1.line(x, sin(frameCount) * 50, x, y);
	}

	image(bg1, 0, height / 2);
}

// --- Layer: colored trace ---
function Layer2() {
	// semi-transparent background for color trail
	bg2.background(180, 90, 90, 0.3);

	for (let x = 0; x < width / 2; x += 2) {
		var nx = 0.05 * x;
		var nt = sin(frameCount * 0.03) * 0.55;

		var y = 150 * noise(nx, nt);

		bg2.stroke(270, 90, 90, 0.3);
		bg2.strokeWeight(2);
		bg2.line(x, 0, x, y);
	}

	image(bg2, width / 2, height / 2);
}

// --- Layer: colored no trace ---
function Layer3() {
	bg3.clear();

	for (let x = 0; x < width / 2; x += 2) {
		var nx = 0.05 * x;
		var nt = sin(frameCount * 0.03) * 0.55;

		var y = 150 * noise(nx, nt);

		bg3.stroke(270, 90, 90, 0.3);
		bg3.strokeWeight(2);

		// sine offset
		bg3.line(x, sin(frameCount) * 50, x, y);
	}

	image(bg3, width / 2, 0);
}

